def build(world):
    def walk_to(gx, gy, radius, limit):
        seen = set()
        tried = set()
        for _ in range(limit):
            tx, ty = world.tile()
            if max(abs(tx - gx), abs(ty - gy)) <= radius:
                return True
            seen.add((tx, ty))
            options = []
            for direction, nx, ny in (
                ("N", tx, ty - 1),
                ("E", tx + 1, ty),
                ("S", tx, ty + 1),
                ("W", tx - 1, ty),
            ):
                if (tx, ty, direction) in tried:
                    continue
                distance = abs(nx - gx) + abs(ny - gy)
                options.append((distance, direction, nx, ny))
            options = sorted(options)
            moved = False
            for _, direction, nx, ny in options:
                before = world.tile()
                world.move(direction, "step")
                after = world.tile()
                tried.add((before[0], before[1], direction))
                if after != before:
                    moved = True
                    break
            if not moved:
                return False
        tx, ty = world.tile()
        return max(abs(tx - gx), abs(ty - gy)) <= radius

    target = world.patch()
    if target is not None:
        walk_to(int(target[0]), int(target[1]), 6, 100)

    ores = world.ore_tiles("iron-ore")
    if not ores and target is not None:
        walk_to(int(target[0]), int(target[1]), 2, 80)
        ores = world.ore_tiles("iron-ore")
    if not ores:
        return

    px, py = world.tile()
    if target is None:
        target_x, target_y = px, py
    else:
        target_x, target_y = target[0], target[1]

    layouts = []
    seen_layouts = set()
    blocked = world.blocked_tiles()
    for ox, oy in ores:
        for dx in (ox, ox - 1):
            for dy in (oy, oy - 1):
                for facing, fx, fy in (
                    ("S", dx, dy + 2),
                    ("N", dx, dy - 2),
                    ("E", dx + 2, dy),
                    ("W", dx - 2, dy),
                ):
                    key = (dx, dy, facing)
                    if key in seen_layouts:
                        continue
                    seen_layouts.add(key)
                    footprint = []
                    for xx in (dx, dx + 1):
                        for yy in (dy, dy + 1):
                            footprint.append((xx, yy))
                    for xx in (fx, fx + 1):
                        for yy in (fy, fy + 1):
                            footprint.append((xx, yy))
                    blocked_here = False
                    for tile in blocked:
                        if tile in footprint:
                            blocked_here = True
                            break
                    if blocked_here:
                        continue
                    stand_x, stand_y = dx - 2, dy - 2
                    score = (
                        abs(px - stand_x) + abs(py - stand_y)
                        + abs(dx - target_x) + abs(dy - target_y)
                    )
                    layouts.append((score, dx, dy, facing, fx, fy))

    layouts = sorted(layouts)
    for _, dx, dy, facing, fx, fy in layouts:
        if world.decisions_left() < 10:
            return
        walk_to(dx - 2, dy - 2, 1, 35)
        if not world.place("burner-mining-drill", dx, dy, facing):
            continue
        if not world.place("stone-furnace", fx, fy, "N"):
            entities = world.entities()
            drill = None
            best = None
            for entity in entities:
                if entity.kind == "mining-drill" and entity.facing == facing:
                    distance = abs(entity.x - (dx + 1)) + abs(entity.y - (dy + 1))
                    if best is None or distance < best:
                        best = distance
                        drill = entity
            if drill is not None:
                world.mine(drill)
            continue

        entities = world.entities()
        drill = None
        furnace = None
        drill_best = None
        furnace_best = None
        for entity in entities:
            if entity.kind == "mining-drill" and entity.facing == facing:
                distance = abs(entity.x - (dx + 1)) + abs(entity.y - (dy + 1))
                if drill_best is None or distance < drill_best:
                    drill_best = distance
                    drill = entity
            if entity.kind == "furnace":
                distance = abs(entity.x - (fx + 1)) + abs(entity.y - (fy + 1))
                if furnace_best is None or distance < furnace_best:
                    furnace_best = distance
                    furnace = entity

        if drill is not None and furnace is not None:
            if not world.give(drill, "coal", 20):
                world.give(drill, "coal", 5)
            if not world.give(furnace, "coal", 20):
                world.give(furnace, "coal", 5)
            return

