def build(world):
    def obstacles():
        blocked = set(world.blocked_tiles())
        for e in world.entities():
            if e.kind == "mining-drill" or e.kind == "furnace":
                ax = int(round(e.x - 1))
                ay = int(round(e.y - 1))
                for dx in range(2):
                    for dy in range(2):
                        blocked.add((ax + dx, ay + dy))
            else:
                blocked.add((int(round(e.x)), int(round(e.y))))
        return blocked

    def entity_at(kind, x, y):
        for e in world.entities():
            if e.kind == kind and abs(e.x - (x + 1)) < 0.6 and abs(e.y - (y + 1)) < 0.6:
                return e
        return None

    def route(start, goals, blocked):
        goals = set(goals)
        if not goals:
            return None, None
        if start in goals:
            return [], start

        min_x = min([start[0]] + [p[0] for p in goals]) - 2
        max_x = max([start[0]] + [p[0] for p in goals]) + 2
        min_y = min([start[1]] + [p[1] for p in goals]) - 2
        max_y = max([start[1]] + [p[1] for p in goals]) + 2

        queue = [start]
        parent = {start: None}
        direction = {}
        end = None
        index = 0

        while index < len(queue) and end is None:
            x, y = queue[index]
            index += 1
            for d, q in [
                ("N", (x, y - 1)),
                ("E", (x + 1, y)),
                ("S", (x, y + 1)),
                ("W", (x - 1, y))
            ]:
                if q in parent:
                    continue
                if q[0] < min_x or q[0] > max_x or q[1] < min_y or q[1] > max_y:
                    continue
                if q in blocked:
                    continue
                parent[q] = (x, y)
                direction[q] = d
                if q in goals:
                    end = q
                    break
                queue.append(q)

        if end is None:
            return None, None

        path = []
        p = end
        while p != start:
            path.append(direction[p])
            p = parent[p]
        path.reverse()
        return path, end

    def take_path_step(path):
        direction = path[0]
        straight = 0
        for d in path:
            if d != direction:
                break
            straight += 1
        if straight >= 5:
            world.move(direction, "long")
        else:
            world.move(direction, "step")

    def find_candidates(ore, blocked, failed):
        candidates = []
        for ox, oy in ore:
            for dx in [-1, 0]:
                for dy in [-1, 0]:
                    x = ox + dx
                    y = oy + dy
                    for facing in ["N", "E", "S", "W"]:
                        if facing == "S":
                            drop_x, drop_y = x + 1.5, y + 2.3
                        elif facing == "N":
                            drop_x, drop_y = x + 0.5, y - 0.3
                        elif facing == "E":
                            drop_x, drop_y = x + 2.3, y + 0.5
                        else:
                            drop_x, drop_y = x - 0.3, y + 1.5

                        fx0 = int(math.floor(drop_x))
                        fy0 = int(math.floor(drop_y))
                        for fx in [fx0 - 1, fx0]:
                            for fy in [fy0 - 1, fy0]:
                                drill_tiles = [
                                    (x, y), (x + 1, y),
                                    (x, y + 1), (x + 1, y + 1)
                                ]
                                furnace_tiles = [
                                    (fx, fy), (fx + 1, fy),
                                    (fx, fy + 1), (fx + 1, fy + 1)
                                ]
                                if any(tile in furnace_tiles for tile in drill_tiles):
                                    continue
                                if any(tile in blocked for tile in drill_tiles + furnace_tiles):
                                    continue
                                candidate = (x, y, fx, fy, facing)
                                if candidate not in failed and candidate not in candidates:
                                    candidates.append(candidate)
        return candidates

    def stand_goals(candidates, blocked):
        owners = {}
        for candidate in candidates:
            x, y, fx, fy, facing = candidate
            machine_tiles = {
                (x, y), (x + 1, y), (x, y + 1), (x + 1, y + 1),
                (fx, fy), (fx + 1, fy), (fx, fy + 1), (fx + 1, fy + 1)
            }
            for sx in range(min(x, fx) - 5, max(x + 1, fx + 1) + 6):
                for sy in range(min(y, fy) - 5, max(y + 1, fy + 1) + 6):
                    if max(abs(sx - x), abs(sy - y)) > 5:
                        continue
                    if max(abs(sx - fx), abs(sy - fy)) > 5:
                        continue
                    if (sx, sy) in blocked or (sx, sy) in machine_tiles:
                        continue
                    owners[(sx, sy)] = candidate
        return owners

    failed = set()

    while world.decisions_left() > 20:
        blocked = obstacles()
        candidates = find_candidates(world.ore_tiles("iron-ore"), blocked, failed)
        owners = stand_goals(candidates, blocked)

        if not owners:
            marker = world.patch()
            if marker is None:
                return
            px = int(round(marker[0]))
            py = int(round(marker[1]))
            goals = []
            for gx in range(px - 7, px + 8):
                for gy in range(py - 7, py + 8):
                    if (gx, gy) not in blocked:
                        goals.append((gx, gy))
            path, end = route(world.tile(), goals, blocked)
            if path is None or not path:
                return
            take_path_step(path)
            continue

        path, end = route(world.tile(), owners.keys(), blocked)
        if path is None:
            failed.update(candidates)
            continue
        if path:
            take_path_step(path)
            continue

        x, y, fx, fy, facing = owners[end]
        furnace_placed = world.place("stone-furnace", fx, fy, "N")
        furnace = entity_at("furnace", fx, fy) if furnace_placed else None
        if furnace is None:
            failed.add((x, y, fx, fy, facing))
            continue

        drill_placed = world.place("burner-mining-drill", x, y, facing)
        drill = entity_at("mining-drill", x, y) if drill_placed else None

        if drill is None:
            furnace = entity_at("furnace", fx, fy)
            if furnace is not None:
                world.mine(furnace.row)
            failed.add((x, y, fx, fy, facing))
            continue

        drill = entity_at("mining-drill", x, y)
        furnace = entity_at("furnace", fx, fy)
        if drill is None or furnace is None:
            if drill is not None:
                world.mine(drill.row)
            furnace = entity_at("furnace", fx, fy)
            if furnace is not None:
                world.mine(furnace.row)
            failed.add((x, y, fx, fy, facing))
            continue

        world.give(drill.row, "coal", 20)
        furnace = entity_at("furnace", fx, fy)
        if furnace is not None:
            world.give(furnace.row, "coal", 20)

        drill = entity_at("mining-drill", x, y)
        furnace = entity_at("furnace", fx, fy)
        if drill is not None and furnace is not None and drill.fuel > 0 and furnace.fuel > 0:
            return

        if drill is not None and drill.fuel <= 0:
            world.give(drill.row, "coal", 20)
        furnace = entity_at("furnace", fx, fy)
        if furnace is not None and furnace.fuel <= 0:
            world.give(furnace.row, "coal", 20)
        return

