def build(world):
    blocked = set(world.blocked_tiles())
    occupied = set()

    for e in world.entities():
        if e.kind == "furnace" or e.kind == "mining-drill":
            ex = int(round(e.x)) - 1
            ey = int(round(e.y)) - 1
            for xx in range(ex, ex + 2):
                for yy in range(ey, ey + 2):
                    occupied.add((xx, yy))
        else:
            occupied.add((int(math.floor(e.x)), int(math.floor(e.y))))

    unavailable = blocked | occupied

    def locate(kind, x, y):
        best = None
        best_distance = None
        for entity in world.entities():
            if entity.kind == kind:
                distance = abs(entity.x - (x + 1)) + abs(entity.y - (y + 1))
                if best_distance is None or distance < best_distance:
                    best = entity
                    best_distance = distance
        if best_distance is not None and best_distance < 0.1:
            return best
        return None

    def remove_at(kind, x, y):
        entity = locate(kind, x, y)
        if entity is not None and world.decisions_left() > 0:
            world.mine(entity.row)

    def fuel_machine(kind, x, y):
        for amount in (20, 5, 1):
            if world.decisions_left() <= 0:
                return False
            entity = locate(kind, x, y)
            if entity is None:
                return False
            if entity.fuel > 0:
                return True
            if world.inventory()["coal"] < amount:
                continue
            world.give(entity.row, "coal", amount)
            entity = locate(kind, x, y)
            if entity is not None and entity.fuel > 0:
                return True
        return False

    orientations = [
        ("S", 0, 2),
        ("N", 0, -2),
        ("E", 2, 0),
        ("W", -2, 0),
    ]

    candidates = []
