    start = world.tile()

    for ox, oy in world.ore_tiles("iron-ore"):
        for dx in (ox - 1, ox):
            for dy in (oy - 1, oy):
                for facing, fxoff, fyoff in orientations:
                    key = (dx, dy, facing)
                    if key in seen:
                        continue
                    seen.add(key)
                    fx = dx + fxoff
                    fy = dy + fyoff
                    clear = True
                    for xx in range(dx, dx + 2):
                        for yy in range(dy, dy + 2):
                            if (xx, yy) in unavailable:
                                clear = False
                    for xx in range(fx, fx + 2):
                        for yy in range(fy, fy + 2):
                            if (xx, yy) in unavailable:
                                clear = False
                    if clear:
                        score = abs(dx - start[0]) + abs(dy - start[1])
                        score += abs(fx - start[0]) + abs(fy - start[1])
                        candidates.append((score, dx, dy, facing, fx, fy))

    candidates = sorted(candidates)

    def walk_near(dx, dy, fx, fy, drill_tiles, furnace_tiles):
