                    here not in drill_tiles and here not in furnace_tiles):
                return True

            queue = [here]
            parent = {here: here}
            first_direction = {}
            goal = None
            index = 0
            directions = [
                (0, -1, "N"),
                (1, 0, "E"),
                (0, 1, "S"),
