        if not fuel_machine("mining-drill", dx, dy):
            remove_at("furnace", fx, fy)
            remove_at("mining-drill", dx, dy)
            continue

        if not fuel_machine("furnace", fx, fy):
            remove_at("furnace", fx, fy)
