            ex = floor_tile(e.x)
            ey = floor_tile(e.y)
            if e.kind == "wall":
                blocked.add((ex, ey))
            elif e.kind == "mining-drill" or e.kind == "furnace":
                for ox in range(-1, 1):
                    for oy in range(-1, 1):
                        blocked.add((ex + ox, ey + oy))
            elif e.kind == "container" or e.kind == "other":
                blocked.add((ex, ey))
        return blocked

