                if e.kind == "mining-drill":
                    d = abs(e.x - (dx + 1)) + abs(e.y - (dy + 1))
                    if drill_dist is None or d < drill_dist:
                        drill_dist = d
                        drill_row = e.row
                elif e.kind == "furnace":
                    d = abs(e.x - (fx + 1)) + abs(e.y - (fy + 1))
                    if furnace_dist is None or d < furnace_dist:
                        furnace_dist = d
                        furnace_row = e.row

            if drill_row is not None:
                world.give(drill_row, "coal", 20)
            if furnace_row is not None:
                world.give(furnace_row, "coal", 20)

            for i in range(120):
                if world.decisions_left() <= 0:
                    break
                world.wait()
            return

        if placed:
            return
